package com.slayerprep;

import com.slayerprep.GearData.Footnote;
import com.slayerprep.GearData.StyleTable;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * Picks, per attack style and slot, the best wiki-ranked entry the player owns, honouring the wiki's footnotes:
 * <ul>
 * <li>a footnote shared by entries in two or more armour/weapon slots that speaks of a "full" set (Void, crystal +
 * bow of Faerdhinen, ...) marks a <em>set</em> that is used as a whole or not at all; the set is used when it scores
 * better than the loose picks;</li>
 * <li>a footnote that links other items of the table ("If bringing a twisted bow") makes its entries depend on one
 * of those items being chosen; a note mentioning a crossbow depends on a crossbow being chosen;</li>
 * <li>any other footnote shared across slots is treated as a set too (Inquisitor's "with a crush weapon");
 * the rest is informational and shown with the choice.</li>
 * </ul>
 */
@Slf4j
public class GearAdvisor
{
	static final List<String> SLOT_ORDER = List.of(
		"head", "neck", "cape", "body", "legs", "weapon", "2h", "shield", "ammo", "hands", "feet", "ring", "special");
	/** Slots whose shared footnotes describe a set; "special" is a spec weapon, not part of an outfit. */
	private static final Set<String> SET_SLOTS = Set.of(
		"head", "neck", "cape", "body", "legs", "weapon", "2h", "shield", "ammo", "hands", "feet", "ring");
	private static final String CROSSBOW = "crossbow";
	/** Wiki wording for a set that must be worn as a whole: "With full Elite Void", "full crystal armour". */
	private static final String FULL_SET = "full";

	private final Map<String, List<String>> aliases;

	public GearAdvisor(Map<String, List<String>> aliases)
	{
		Map<String, List<String>> normalized = new HashMap<>();
		aliases.forEach((name, items) -> normalized.put(ItemMatcher.normalize(name), List.copyOf(items)));
		this.aliases = normalized;
	}

	public Map<String, Map<String, SlotChoice>> advise(GearData.GearTask task, ItemSnapshot snapshot)
	{
		Map<String, Map<String, SlotChoice>> result = new LinkedHashMap<>();
		task.getStyles().forEach((style, table) -> result.put(style, adviseStyle(table, snapshot)));
		return result;
	}

	private Map<String, SlotChoice> adviseStyle(StyleTable table, ItemSnapshot snapshot)
	{
		Table t = new Table(table);
		Assignment best = assign(t, snapshot, null);
		for (String set : t.sets.keySet())
		{
			if (!setCompletable(t, snapshot, set))
			{
				continue;
			}
			Assignment withSet = assign(t, snapshot, set);
			if (withSet.score < best.score)
			{
				best = withSet;
			}
		}
		return best.choices;
	}

	/** All slots of a set have an owned member. */
	private boolean setCompletable(Table t, ItemSnapshot snapshot, String set)
	{
		for (String slot : t.sets.get(set))
		{
			boolean owned = false;
			for (List<String> entry : t.table.getSlots().get(slot))
			{
				for (String alternative : entry)
				{
					if (t.table.notesFor(alternative).contains(set) && owned(slot, alternative, snapshot).isPresent())
					{
						owned = true;
					}
				}
			}
			if (!owned)
			{
				return false;
			}
		}
		return true;
	}

	private Assignment assign(Table t, ItemSnapshot snapshot, @Nullable String activeSet)
	{
		Assignment assignment = new Assignment();
		for (String slot : SLOT_ORDER)
		{
			List<List<String>> ranked = t.table.getSlots().get(slot);
			if (ranked == null || ranked.isEmpty())
			{
				continue;
			}
			SlotChoice choice = adviseSlot(t, slot, ranked, snapshot, activeSet, assignment);
			assignment.choices.put(slot, choice);
			assignment.score += choice.getItemName() == null ? ranked.size() + 1 : assignment.rankOfLast;
		}
		return assignment;
	}

	private SlotChoice adviseSlot(Table t, String slot, List<List<String>> ranked, ItemSnapshot snapshot,
		@Nullable String activeSet, Assignment assignment)
	{
		String topEntry = null;
		for (int rank = 0; rank < ranked.size(); rank++)
		{
			List<String> labels = new ArrayList<>();
			for (String alternative : ranked.get(rank))
			{
				if (!eligible(t, slot, alternative, activeSet, assignment))
				{
					continue;
				}
				if (!resolve(slot, alternative).isEmpty())
				{
					labels.add(alternative);
				}
				Optional<Owned> owned = owned(slot, alternative, snapshot);
				if (owned.isPresent())
				{
					assignment.rankOfLast = rank;
					assignment.chosenNames.add(ItemMatcher.normalize(alternative));
					return new SlotChoice(alternative, owned.get().name, owned.get().ownership, topEntry, noteFor(t, alternative));
				}
			}
			if (topEntry == null && !labels.isEmpty())
			{
				topEntry = String.join(" / ", labels);
			}
		}
		return new SlotChoice(null, null, Ownership.MISSING, topEntry, null);
	}

	private boolean eligible(Table t, String slot, String alternative, @Nullable String activeSet, Assignment assignment)
	{
		List<String> notes = t.table.notesFor(alternative);
		if (activeSet != null && t.sets.get(activeSet).contains(slot) && !notes.contains(activeSet))
		{
			return false; // a set slot only takes members of the active set
		}
		for (String note : notes)
		{
			if (t.sets.containsKey(note))
			{
				if (!note.equals(activeSet))
				{
					return false; // member of a set that is not in use
				}
				continue;
			}
			Set<String> dependencies = t.dependencies.getOrDefault(note, Set.of());
			if (!dependencies.isEmpty() && dependencies.stream().noneMatch(assignment.chosenNames::contains))
			{
				return false;
			}
			if (t.crossbowNotes.contains(note) && assignment.chosenNames.stream().noneMatch(n -> n.contains(CROSSBOW)))
			{
				return false;
			}
		}
		return true;
	}

	@Nullable
	private static String noteFor(Table t, String alternative)
	{
		List<String> texts = new ArrayList<>();
		for (String note : t.table.notesFor(alternative))
		{
			Footnote footnote = t.table.getFootnotes().get(note);
			if (footnote != null && !footnote.getText().isEmpty())
			{
				texts.add(footnote.getText());
			}
		}
		return texts.isEmpty() ? null : String.join(" ", texts);
	}

	private Optional<Owned> owned(String slot, String alternative, ItemSnapshot snapshot)
	{
		for (String candidate : resolve(slot, alternative))
		{
			ItemMatcher matcher = ItemMatcher.item(candidate);
			Optional<String> name = snapshot.findName(matcher);
			if (name.isPresent())
			{
				return Optional.of(new Owned(name.get(), snapshot.find(matcher)));
			}
		}
		return Optional.empty();
	}

	/** Expand a wiki entry name to in-game item names; unknown group names resolve to nothing. */
	private List<String> resolve(String slot, String name)
	{
		String key = ItemMatcher.normalize(name);
		List<String> slotSpecific = aliases.get(key + "#" + slot);
		if (slotSpecific != null)
		{
			return slotSpecific;
		}
		List<String> generic = aliases.get(key);
		if (generic != null)
		{
			return generic;
		}
		if (key.contains("#"))
		{
			log.debug("Skipping unknown wiki group name {}", name);
			return List.of();
		}
		return List.of(name);
	}

	/** Footnote analysis of one table: which notes are sets, and what the other notes depend on. */
	private static class Table
	{
		private final StyleTable table;
		/** set note name to the slots it spans. */
		private final Map<String, Set<String>> sets = new LinkedHashMap<>();
		/** dependency note name to normalised names of table items it requires (any one of them). */
		private final Map<String, Set<String>> dependencies = new HashMap<>();
		private final Set<String> crossbowNotes = new HashSet<>();

		Table(StyleTable table)
		{
			this.table = table;
			Map<String, String> slotOfItem = new HashMap<>();
			Map<String, Set<String>> slotsOfNote = new LinkedHashMap<>();
			table.getSlots().forEach((slot, ranked) -> ranked.forEach(entry -> entry.forEach(alternative ->
			{
				slotOfItem.putIfAbsent(ItemMatcher.normalize(alternative), slot);
				for (String note : table.notesFor(alternative))
				{
					slotsOfNote.computeIfAbsent(note, k -> new HashSet<>()).add(slot);
				}
			})));
			slotsOfNote.forEach((note, slots) ->
			{
				Footnote footnote = table.getFootnotes().get(note);
				String text = footnote == null ? "" : footnote.getText().toLowerCase(Locale.ROOT);
				Set<String> setSlots = slots.stream().filter(SET_SLOTS::contains).collect(Collectors.toSet());
				if (setSlots.size() >= 2 && text.contains(FULL_SET))
				{
					sets.put(note, setSlots);
					return;
				}
				Set<String> required = new HashSet<>();
				if (footnote != null)
				{
					for (String item : footnote.getItems())
					{
						String key = ItemMatcher.normalize(item);
						String itemSlot = slotOfItem.get(key);
						if (itemSlot != null && !slots.contains(itemSlot))
						{
							required.add(key);
						}
					}
				}
				if (!required.isEmpty())
				{
					dependencies.put(note, required);
				}
				else if (text.contains(CROSSBOW))
				{
					crossbowNotes.add(note);
				}
				else if (setSlots.size() >= 2)
				{
					sets.put(note, setSlots);
				}
			});
		}
	}

	private static class Assignment
	{
		private final Map<String, SlotChoice> choices = new LinkedHashMap<>();
		private final Set<String> chosenNames = new HashSet<>();
		private int score;
		private int rankOfLast;
	}

	private static class Owned
	{
		private final String name;
		private final Ownership ownership;

		Owned(String name, Ownership ownership)
		{
			this.name = name;
			this.ownership = ownership;
		}
	}

	/**
	 * Order style names by a comma-separated preference list ("Melee, Ranged, Magic"); a style matches a
	 * preference when it contains it, with an exact match ranked first within its group. Unmatched styles
	 * go last. Remaining ties are broken alphabetically.
	 */
	public static List<String> orderStyles(Collection<String> styles, String preference)
	{
		List<String> prefs = Arrays.stream(preference.split(","))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.map(s -> s.toLowerCase(Locale.ROOT))
			.collect(Collectors.toList());
		Comparator<String> byPreference = Comparator.comparingInt(style ->
		{
			String lower = style.toLowerCase(Locale.ROOT);
			for (int i = 0; i < prefs.size(); i++)
			{
				if (lower.contains(prefs.get(i)))
				{
					return i;
				}
			}
			return prefs.size();
		});
		Comparator<String> exactFirst = Comparator.comparingInt(style -> prefs.contains(style.toLowerCase(Locale.ROOT)) ? 0 : 1);
		return styles.stream()
			.sorted(byPreference.thenComparing(exactFirst).thenComparing(String.CASE_INSENSITIVE_ORDER))
			.collect(Collectors.toList());
	}
}

package com.slayerprep;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * Recommended equipment per task and attack style, generated from the OSRS Wiki by tools/fetch_wiki_gear.py.
 */
public class GearData
{
	private static final String GEAR_RESOURCE = "gear.json";
	private static final String ALIASES_RESOURCE = "aliases.json";

	/** A wiki footnote attached to one or more table entries. */
	public static class Footnote
	{
		private String text;
		/** Item page names linked from the note text. */
		private List<String> items;

		public String getText()
		{
			return text == null ? "" : text;
		}

		public List<String> getItems()
		{
			return items == null ? Collections.emptyList() : items;
		}
	}

	/** One "Recommended equipment" table: an attack style with its slots and footnotes. */
	public static class StyleTable
	{
		/** slot name to ranked entries, each entry a list of equally good alternatives. */
		private Map<String, List<List<String>>> slots;
		/** item name to the names of the footnotes attached to it. */
		private Map<String, List<String>> notes;
		private Map<String, Footnote> footnotes;

		public Map<String, List<List<String>>> getSlots()
		{
			return slots == null ? Collections.emptyMap() : slots;
		}

		public List<String> notesFor(String item)
		{
			List<String> names = notes == null ? null : notes.get(item);
			return names == null ? Collections.emptyList() : names;
		}

		public Map<String, Footnote> getFootnotes()
		{
			return footnotes == null ? Collections.emptyMap() : footnotes;
		}
	}

	public static class GearTask
	{
		@Getter
		private String page;
		/** style name to its equipment table. */
		private Map<String, StyleTable> styles;
		/** Variant monsters that count for this task and have their own table, in display order. */
		private Map<String, GearTask> variants;

		public Map<String, StyleTable> getStyles()
		{
			return styles == null ? Collections.emptyMap() : styles;
		}

		public Map<String, GearTask> getVariants()
		{
			return variants == null ? Collections.emptyMap() : variants;
		}

		boolean hasStyles()
		{
			return !getStyles().isEmpty();
		}
	}

	private static class GearFile
	{
		private String source;
		/** wiki item page name to item id, for icons. */
		private Map<String, Integer> items;
		private GearTask generic;
		private Map<String, GearTask> tasks;
		private List<String> missing;
	}

	public static final String GENERIC_LABEL = "Generic slayer gear";

	private final Map<String, GearTask> tasksByName;
	private final Map<String, Integer> itemIds;
	@Nullable
	private final GearTask generic;

	private GearData(GearFile file)
	{
		Map<String, Integer> ids = new HashMap<>();
		if (file.items != null)
		{
			file.items.forEach((name, id) ->
			{
				if (name != null && id != null)
				{
					ids.put(ItemMatcher.normalize(name), id);
				}
			});
		}
		itemIds = Collections.unmodifiableMap(ids);
		generic = file.generic != null && file.generic.hasStyles() ? file.generic : null;
		Map<String, GearTask> byName = new HashMap<>();
		if (file.tasks != null)
		{
			file.tasks.forEach((name, task) ->
			{
				if (task != null && (task.styles != null || task.variants != null))
				{
					byName.put(key(name), task);
				}
			});
		}
		tasksByName = Collections.unmodifiableMap(byName);
	}

	private static String key(String taskName)
	{
		return taskName.trim().toLowerCase(Locale.ROOT);
	}

	public static GearData parse(Gson gson, Reader reader)
	{
		GearFile file = gson.fromJson(reader, GearFile.class);
		if (file == null)
		{
			throw new JsonParseException("gear data is empty");
		}
		return new GearData(file);
	}

	public static GearData load(Gson gson) throws IOException
	{
		try (Reader reader = openResource(GEAR_RESOURCE))
		{
			return parse(gson, reader);
		}
	}

	public static Map<String, List<String>> parseAliases(Gson gson, Reader reader)
	{
		Map<String, List<String>> aliases = gson.fromJson(reader, new TypeToken<Map<String, List<String>>>()
		{
		}.getType());
		return aliases == null ? Collections.emptyMap() : aliases;
	}

	public static Map<String, List<String>> loadAliases(Gson gson) throws IOException
	{
		try (Reader reader = openResource(ALIASES_RESOURCE))
		{
			return parseAliases(gson, reader);
		}
	}

	private static Reader openResource(String name) throws IOException
	{
		InputStream in = GearData.class.getResourceAsStream(name);
		if (in == null)
		{
			throw new IOException("missing resource " + name);
		}
		return new InputStreamReader(in, StandardCharsets.UTF_8);
	}

	/** Item id for a wiki item name, used for icons. */
	public Optional<Integer> itemId(String itemName)
	{
		return Optional.ofNullable(itemIds.get(ItemMatcher.normalize(itemName)));
	}

	/** The task's own gear table, if the wiki has one. */
	public Optional<GearTask> forTask(String taskName)
	{
		return Optional.ofNullable(tasksByName.get(key(taskName))).filter(GearTask::hasStyles);
	}

	/**
	 * Every gear table that applies to a task: the task's own table first, then variant monsters,
	 * then the generic slayer table. Empty only when the data file has none of these.
	 */
	public List<GearOption> optionsFor(String taskName)
	{
		List<GearOption> options = new ArrayList<>();
		GearTask task = tasksByName.get(key(taskName));
		if (task != null)
		{
			if (task.hasStyles())
			{
				options.add(new GearOption(taskName, GearOption.Kind.TASK, task));
			}
			task.getVariants().forEach((name, variant) ->
			{
				if (variant != null && variant.hasStyles())
				{
					options.add(new GearOption(name, GearOption.Kind.VARIANT, variant));
				}
			});
		}
		if (generic != null)
		{
			options.add(new GearOption(GENERIC_LABEL, GearOption.Kind.GENERIC, generic));
		}
		return options;
	}

	/** Every item name mentioned in any gear table, normalised. */
	public Set<String> allItemNames()
	{
		Set<String> names = new HashSet<>();
		for (GearTask task : tasksByName.values())
		{
			collectNames(task, names);
			task.getVariants().values().forEach(v -> collectNames(v, names));
		}
		if (generic != null)
		{
			collectNames(generic, names);
		}
		return names;
	}

	private static void collectNames(GearTask task, Set<String> names)
	{
		for (StyleTable style : task.getStyles().values())
		{
			for (List<List<String>> ranked : style.getSlots().values())
			{
				for (List<String> entry : ranked)
				{
					for (String name : entry)
					{
						names.add(ItemMatcher.normalize(name));
					}
				}
			}
		}
	}
}

package com.slayerprep;

import lombok.Value;

/**
 * One selectable source of gear advice for a task: the task's own wiki table, a variant monster's table,
 * or the generic slayer table.
 */
@Value
public class GearOption
{
	public enum Kind
	{
		TASK,
		VARIANT,
		GENERIC
	}

	String label;
	Kind kind;
	GearData.GearTask task;
}

package com.slayerprep;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Case-insensitive item name matcher. Names are normalised before comparison so that
 * charge/dose states such as "(4)", "(uncharged)" or "(p++)" are ignored while real
 * variants such as "(i)", "(f)", "(or)", "(e)", "(t)" and "(g)" are kept.
 */
@Value
public class ItemMatcher
{
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");
	private static final Pattern PAREN = Pattern.compile("\\s*\\(");
	private static final Pattern STATE_SUFFIX = Pattern.compile(
		"\\s*\\((?:\\d+|uncharged|empty|full|p|p\\+|p\\+\\+|unf|inactive)\\)$");
	private static final Pattern DEGRADE_SUFFIX = Pattern.compile(" \\d+$");
	private static final String SLAYER_HELMET = "slayer helmet";
	private static final String SLAYER_HELMET_IMBUED = "slayer helmet (i)";

	public enum Mode
	{
		EXACT,
		PREFIX,
		CONTAINS,
		/** Exact, but also accepts a trailing degrade/tier number ("Ahrim's robetop 100", "Ardougne cloak 4"). */
		ITEM
	}

	String name;
	String pattern;
	Mode mode;

	public static ItemMatcher exact(String name)
	{
		return new ItemMatcher(name, normalize(name), Mode.EXACT);
	}

	public static ItemMatcher prefix(String name)
	{
		return new ItemMatcher(name, normalize(name), Mode.PREFIX);
	}

	public static ItemMatcher contains(String name)
	{
		return new ItemMatcher(name, normalize(name), Mode.CONTAINS);
	}

	/** Any Slayer helmet variant: plain, imbued, or any recolour of either. */
	public static ItemMatcher slayerHelmet()
	{
		return new ItemMatcher("Slayer helmet", SLAYER_HELMET, Mode.CONTAINS);
	}

	/** Matcher for a wiki gear entry, which names the item page rather than a specific in-game variant. */
	public static ItemMatcher item(String name)
	{
		String normalized = normalize(name);
		if (normalized.endsWith(SLAYER_HELMET_IMBUED))
		{
			return new ItemMatcher(name, SLAYER_HELMET_IMBUED, Mode.CONTAINS);
		}
		if (normalized.endsWith(SLAYER_HELMET))
		{
			return new ItemMatcher(name, SLAYER_HELMET, Mode.CONTAINS);
		}
		return new ItemMatcher(name, normalized, Mode.ITEM);
	}

	public static String normalize(String raw)
	{
		String s = WHITESPACE.matcher(raw.toLowerCase(Locale.ROOT).trim()).replaceAll(" ");
		s = PAREN.matcher(s).replaceAll(" (");
		Matcher m = STATE_SUFFIX.matcher(s);
		while (m.find())
		{
			s = s.substring(0, m.start()).trim();
			m = STATE_SUFFIX.matcher(s);
		}
		return s.trim();
	}

	public boolean matches(String itemName)
	{
		String candidate = normalize(itemName);
		switch (mode)
		{
			case EXACT:
				return candidate.equals(pattern);
			case PREFIX:
				return candidate.startsWith(pattern);
			case CONTAINS:
				return candidate.contains(pattern);
			case ITEM:
				return candidate.equals(pattern)
					|| (candidate.startsWith(pattern + " ") && DEGRADE_SUFFIX.matcher(candidate.substring(pattern.length())).matches());
			default:
				return false;
		}
	}
}

package com.slayerprep;

import java.util.Collections;
import java.util.Map;
import java.util.Optional;
import lombok.Value;

/**
 * Immutable view of what the player owns: item name to quantity for inventory, worn equipment, bank and
 * (for group ironmen) the shared group storage.
 */
@Value
public class ItemSnapshot
{
	private static final ItemSnapshot EMPTY = new ItemSnapshot(
		Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap());

	Map<String, Integer> inventory;
	Map<String, Integer> worn;
	Map<String, Integer> bank;
	Map<String, Integer> groupBank;

	public static ItemSnapshot empty()
	{
		return EMPTY;
	}

	public ItemSnapshot withInventory(Map<String, Integer> items)
	{
		return new ItemSnapshot(Map.copyOf(items), worn, bank, groupBank);
	}

	public ItemSnapshot withWorn(Map<String, Integer> items)
	{
		return new ItemSnapshot(inventory, Map.copyOf(items), bank, groupBank);
	}

	public ItemSnapshot withBank(Map<String, Integer> items)
	{
		return new ItemSnapshot(inventory, worn, Map.copyOf(items), groupBank);
	}

	public ItemSnapshot withGroupBank(Map<String, Integer> items)
	{
		return new ItemSnapshot(inventory, worn, bank, Map.copyOf(items));
	}

	public Ownership find(ItemMatcher matcher)
	{
		if (findIn(inventory, matcher).isPresent() || findIn(worn, matcher).isPresent())
		{
			return Ownership.CARRIED;
		}
		if (findIn(bank, matcher).isPresent())
		{
			return Ownership.IN_BANK;
		}
		if (findIn(groupBank, matcher).isPresent())
		{
			return Ownership.IN_GROUP_BANK;
		}
		return Ownership.MISSING;
	}

	/** The name of the first owned item that matches, preferring carried items, then bank, then group storage. */
	public Optional<String> findName(ItemMatcher matcher)
	{
		Optional<String> name = findIn(worn, matcher);
		if (name.isEmpty())
		{
			name = findIn(inventory, matcher);
		}
		if (name.isEmpty())
		{
			name = findIn(bank, matcher);
		}
		if (name.isEmpty())
		{
			name = findIn(groupBank, matcher);
		}
		return name;
	}

	private static Optional<String> findIn(Map<String, Integer> items, ItemMatcher matcher)
	{
		return items.entrySet().stream()
			.filter(e -> e.getValue() > 0 && matcher.matches(e.getKey()))
			.map(Map.Entry::getKey)
			.findFirst();
	}
}

package com.slayerprep;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.ColorScheme;

/** Where an item is, best first. */
@Getter
@RequiredArgsConstructor
public enum Ownership
{
	CARRIED("With you", ColorScheme.PROGRESS_COMPLETE_COLOR),
	IN_BANK("In bank", ColorScheme.PROGRESS_INPROGRESS_COLOR),
	IN_GROUP_BANK("In group bank", new Color(115, 170, 255)),
	MISSING("Missing", ColorScheme.PROGRESS_ERROR_COLOR);

	private final String label;
	private final Color color;
}

package com.slayerprep;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Everything the panel, overlay and bank tab show for the current task.
 */
@Value
public class PrepResult
{
	public static final PrepResult NO_TASK = new PrepResult(null, Collections.emptyList(), Collections.emptyMap(),
		Collections.emptyList(), null, null, Collections.emptyList(), Collections.emptyMap(), null, false);

	@Nullable
	SlayerTask task;
	List<RequirementStatus> requirements;
	/** style name to slot name to choice, in display order. */
	Map<String, Map<String, SlotChoice>> gear;
	/** Labels of the selectable gear sources for this task, in display order. */
	List<String> gearOptions;
	@Nullable
	String selectedGearOption;
	/** Explains where the gear advice comes from when it is not the task's own table. */
	@Nullable
	String gearNote;
	List<String> notes;
	/** Normalised item name to item id, for every item the panel shows that has a known id. */
	Map<String, Integer> icons;
	/** The style the player looks at in the panel; the readiness check and the bank tab option use it. */
	@Nullable
	String selectedStyle;
	boolean bankKnown;

	@Nullable
	public Integer iconFor(@Nullable String itemName)
	{
		return itemName == null ? null : icons.get(ItemMatcher.normalize(itemName));
	}

	/** Required items the player is not carrying right now. */
	public List<RequirementStatus> requiredNotCarried()
	{
		return requirements.stream()
			.filter(r -> r.isRequired() && r.getOwnership() != Ownership.CARRIED)
			.collect(Collectors.toList());
	}

	/** Labels of required items the player does not own at all. */
	public List<String> requiredMissing()
	{
		return requirements.stream()
			.filter(r -> r.isRequired() && r.getOwnership() == Ownership.MISSING)
			.map(RequirementStatus::getLabel)
			.collect(Collectors.toList());
	}

	/** Chosen items of the selected style that are not carried yet. */
	public List<String> gearInBank()
	{
		Map<String, SlotChoice> slots = selectedStyle == null ? null : gear.get(selectedStyle);
		if (slots == null)
		{
			return Collections.emptyList();
		}
		return slots.values().stream()
			.filter(c -> c.getItemName() != null && c.getOwnership() != Ownership.CARRIED)
			.map(SlotChoice::getItemName)
			.collect(Collectors.toList());
	}

	/** True when every required item and every chosen item of the selected style is carried. */
	public boolean isReady()
	{
		return requiredNotCarried().isEmpty() && gearInBank().isEmpty();
	}
}

package com.slayerprep;

import java.util.List;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * One group of items for a task; owning any one of the alternatives satisfies the group.
 */
@Value
public class Requirement
{
	List<ItemMatcher> alternatives;
	boolean required;

	public static Requirement required(ItemMatcher... alternatives)
	{
		return new Requirement(List.of(alternatives), true);
	}

	public static Requirement recommended(ItemMatcher... alternatives)
	{
		return new Requirement(List.of(alternatives), false);
	}

	public boolean matchesAny(String itemName)
	{
		return alternatives.stream().anyMatch(m -> m.matches(itemName));
	}

	public String getLabel()
	{
		return alternatives.stream().map(ItemMatcher::getName).collect(Collectors.joining(" / "));
	}
}

package com.slayerprep;

import javax.annotation.Nullable;
import lombok.Value;

@Value
public class RequirementStatus
{
	Requirement requirement;
	Ownership ownership;
	/** The owned item that satisfies the requirement, or null when missing. */
	@Nullable
	String itemName;

	public boolean isRequired()
	{
		return requirement.isRequired();
	}

	public String getLabel()
	{
		return itemName != null ? itemName : requirement.getLabel();
	}
}

package com.slayerprep;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptID;
import net.runelite.api.SoundEffectID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;

/**
 * A bank tag, opened from a small button in the bank, that shows only the items the current task needs,
 * grouped under text headers: required items, recommended items, then one group per attack style of the
 * chosen gear set. Filtering and item drawing are done by the core Bank Tags plugin; this class supplies the
 * tag and a layout that leaves an empty row above each group, and draws the header text into that row.
 */
@Slf4j
@Singleton
class SlayerPrepBankTab
{
	static final String TAG = "slayer prep";
	private static final int ROW_SIZE = BankTagsPlugin.BANK_ITEMS_PER_ROW;
	private static final int ROW_HEIGHT = BankTagsPlugin.BANK_ITEM_HEIGHT + BankTagsPlugin.BANK_ITEM_Y_PADDING;
	private static final int HEADER_X = BankTagsPlugin.BANK_ITEM_START_X;
	private static final int HEADER_WIDTH = ROW_SIZE * (BankTagsPlugin.BANK_ITEM_WIDTH + BankTagsPlugin.BANK_ITEM_X_PADDING);
	private static final int HEADER_HEIGHT = 16;
	private static final int HEADER_Y_OFFSET = (BankTagsPlugin.BANK_ITEM_HEIGHT - HEADER_HEIGHT) / 2;
	private static final int HEADER_COLOR = 0xff981f;
	private static final int SUB_HEADER_COLOR = 0xc8c8c8;
	private static final String SPECIAL_SLOT = "special";
	private static final String SPECIAL_TITLE = "Special attack";
	private static final int BUTTON_SIZE = 25;
	private static final int BUTTON_X = 380;
	private static final int BUTTON_Y = 5;
	private static final int OP_VIEW_TAB = 2;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private TagManager tagManager;

	@Inject
	private BankTagsService bankTagsService;

	@Inject
	private BankTagsPlugin bankTagsPlugin;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private SlayerPrepConfig config;

	private final Set<Integer> taggedIds = new HashSet<>();
	private final List<Widget> headerWidgets = new ArrayList<>();
	/** Row index to header, for the current layout. */
	private Map<Integer, Section> headers = Map.of();
	private Layout layout = new Layout(TAG, new int[0]);
	private Supplier<PrepResult> resultSupplier = () -> PrepResult.NO_TASK;
	private Widget background;
	private Widget icon;
	/** Guards against re-applying our layout more than once per bank session, which could loop. */
	private boolean layoutReapplied;

	void startUp(Supplier<PrepResult> resultSupplier)
	{
		this.resultSupplier = resultSupplier;
		tagManager.registerTag(TAG, taggedIds::contains);
	}

	/** Must run on the client thread. */
	void shutDown()
	{
		if (isActive())
		{
			bankTagsService.closeBankTag();
		}
		tagManager.unregisterTag(TAG);
		removeButton();
		hideHeaders();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			layoutReapplied = false;
			headerWidgets.clear(); // the previous bank interface's children are gone
			createButton();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
		{
			return;
		}
		// the core remembers the open tag between bank sessions but not our layout; put it back once
		if (isActive() && !layoutReapplied && bankTagsService.getActiveLayout() != layout)
		{
			layoutReapplied = true;
			refresh(resultSupplier.get());
			relayout();
		}
		syncButton();
		drawHeaders();
	}

	/**
	 * Rebuild the tag contents from the last known bank contents and the current task result.
	 * Must run on the client thread. Relayouts the bank if our tag is showing and the contents changed.
	 *
	 * @return true if the bank was relaid out with a new layout
	 */
	boolean refresh(PrepResult result)
	{
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return false;
		}
		Map<String, List<Integer>> bankIdsByName = indexBank(bank);
		List<Section> sections = new ArrayList<>();
		List<String> missing = result.requiredMissing();
		sections.add(new Section("Required items", requirementSection(result, bankIdsByName, true), false, !missing.isEmpty()));
		if (!missing.isEmpty())
		{
			sections.add(new Section("Missing: " + String.join(", ", missing), List.of(), true, true));
		}
		sections.add(new Section("Recommended items", requirementSection(result, bankIdsByName, false), false, false));
		result.getGear().forEach((style, slots) ->
		{
			if (config.bankTabSelectedStyleOnly() && result.getSelectedStyle() != null && !style.equals(result.getSelectedStyle()))
			{
				return;
			}
			sections.add(new Section(style, styleSection(slots, bankIdsByName, false), false, false));
			sections.add(new Section(SPECIAL_TITLE, styleSection(slots, bankIdsByName, true), true, false));
		});
		Map<Integer, Section> newHeaders = new LinkedHashMap<>();
		int[] positions = layoutSections(sections, newHeaders);
		if (Arrays.equals(positions, layout.getLayout()))
		{
			return false;
		}
		headers = newHeaders;
		layout = new Layout(TAG, positions);
		taggedIds.clear();
		for (int id : positions)
		{
			if (id >= 0)
			{
				taggedIds.add(id);
			}
		}
		if (isActive())
		{
			relayout();
			return true;
		}
		return false;
	}

	/**
	 * Re-open our tag with the current layout. Deferred to the next client tick: opening a tag rebuilds the bank
	 * with a script, and this may be called while the bank's own build script is still running (scripts are
	 * not reentrant).
	 */
	private void relayout()
	{
		clientThread.invokeLater(() ->
		{
			if (isActive() && bankOpen())
			{
				bankTagsPlugin.openTag(TAG, layout, 0);
			}
		});
	}

	private boolean bankOpen()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items != null && !items.isHidden();
	}

	private Map<String, List<Integer>> indexBank(ItemContainer bank)
	{
		Map<String, List<Integer>> byName = new HashMap<>();
		for (Item item : bank.getItems())
		{
			if (item.getId() < 0)
			{
				continue;
			}
			String name = ItemMatcher.normalize(itemManager.getItemComposition(item.getId()).getName());
			byName.computeIfAbsent(name, k -> new ArrayList<>()).add(item.getId());
		}
		return byName;
	}

	private static List<Integer> requirementSection(PrepResult result, Map<String, List<Integer>> bankIdsByName, boolean required)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (RequirementStatus status : result.getRequirements())
		{
			if (status.isRequired() != required)
			{
				continue;
			}
			bankIdsByName.forEach((name, bankIds) ->
			{
				if (status.getRequirement().matchesAny(name))
				{
					ids.addAll(bankIds);
				}
			});
		}
		return new ArrayList<>(ids);
	}

	/** Bank ids of the chosen items of one style: either the worn gear, or only the special attack weapon. */
	private static List<Integer> styleSection(Map<String, SlotChoice> slots, Map<String, List<Integer>> bankIdsByName, boolean special)
	{
		List<Integer> ids = new ArrayList<>();
		for (Map.Entry<String, SlotChoice> slot : slots.entrySet())
		{
			SlotChoice choice = slot.getValue();
			if (choice.getItemName() == null || SPECIAL_SLOT.equals(slot.getKey()) != special)
			{
				continue;
			}
			List<Integer> bankIds = bankIdsByName.get(ItemMatcher.normalize(choice.getItemName()));
			if (bankIds != null)
			{
				ids.add(bankIds.get(0));
			}
		}
		return ids;
	}

	/**
	 * Each non-empty section gets an empty bank row for its header, then its items padded to whole rows.
	 * -1 is an empty slot. Header row indexes are collected into {@code headers}.
	 */
	private static int[] layoutSections(List<Section> sections, Map<Integer, Section> headers)
	{
		List<Integer> positions = new ArrayList<>();
		for (Section section : sections)
		{
			if (section.ids.isEmpty() && !section.force)
			{
				continue;
			}
			headers.put(positions.size() / ROW_SIZE, section);
			for (int i = 0; i < ROW_SIZE; i++)
			{
				positions.add(-1);
			}
			positions.addAll(section.ids);
			while (positions.size() % ROW_SIZE != 0)
			{
				positions.add(-1);
			}
		}
		return positions.stream().mapToInt(Integer::intValue).toArray();
	}

	/** Draw the group headers into the bank item container; called after every bank rebuild. Widgets are reused. */
	private void drawHeaders()
	{
		if (!isActive())
		{
			hideHeaders();
			return;
		}
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null)
		{
			return;
		}
		int i = 0;
		for (Map.Entry<Integer, Section> header : headers.entrySet())
		{
			Widget text;
			if (i < headerWidgets.size())
			{
				text = headerWidgets.get(i);
			}
			else
			{
				text = container.createChild(-1, WidgetType.TEXT);
				text.setOriginalWidth(HEADER_WIDTH);
				text.setOriginalHeight(HEADER_HEIGHT);
				text.setTextShadowed(true);
				headerWidgets.add(text);
			}
			Section section = header.getValue();
			text.setFontId(section.sub ? FontID.PLAIN_11 : FontID.PLAIN_12);
			text.setTextColor(section.sub ? SUB_HEADER_COLOR : HEADER_COLOR);
			text.setOriginalX(HEADER_X);
			text.setOriginalY(header.getKey() * ROW_HEIGHT + HEADER_Y_OFFSET);
			text.setText(section.title);
			text.setHidden(false);
			text.revalidate();
			i++;
		}
		for (; i < headerWidgets.size(); i++)
		{
			headerWidgets.get(i).setHidden(true);
		}
	}

	private void hideHeaders()
	{
		for (Widget w : headerWidgets)
		{
			w.setHidden(true);
		}
	}

	private static class Section
	{
		private final String title;
		private final List<Integer> ids;
		/** A sub-section of the section above it, drawn with a smaller, muted header. */
		private final boolean sub;
		/** Show the header row even when the section has no items (e.g. a "Missing: ..." line). */
		private final boolean force;

		Section(String title, List<Integer> ids, boolean sub, boolean force)
		{
			this.title = title;
			this.ids = ids;
			this.sub = sub;
			this.force = force;
		}
	}

	private boolean isActive()
	{
		return TAG.equals(bankTagsService.getActiveTag());
	}

	private boolean bankTagsEnabled()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof BankTagsPlugin)
			{
				return pluginManager.isPluginEnabled(plugin);
			}
		}
		return false;
	}

	private void toggle(ScriptEvent event)
	{
		if (event.getOp() != OP_VIEW_TAB)
		{
			return;
		}
		if (!bankTagsEnabled())
		{
			client.addChatMessage(ChatMessageType.CONSOLE, "", "Slayer Prep: enable the Bank Tags plugin to use the bank tab.", null);
			return;
		}
		boolean open = !isActive();
		if (open)
		{
			refresh(resultSupplier.get());
		}
		clientThread.invokeLater(() ->
		{
			if (!bankOpen())
			{
				return;
			}
			if (open)
			{
				bankTagsPlugin.openTag(TAG, layout, 0);
			}
			else
			{
				bankTagsService.closeBankTag();
				hideHeaders();
			}
			syncButton();
		});
		client.playSoundEffect(SoundEffectID.UI_BOOP);
	}

	private void createButton()
	{
		Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (parent == null)
		{
			return;
		}
		removeButton();
		background = parent.createChild(-1, WidgetType.GRAPHIC);
		background.setOriginalWidth(BUTTON_SIZE);
		background.setOriginalHeight(BUTTON_SIZE);
		background.setOriginalX(BUTTON_X);
		background.setOriginalY(BUTTON_Y);
		background.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
		background.setName("Slayer prep");
		background.setAction(1, "View tab");
		background.setOnOpListener((JavaScriptCallback) this::toggle);
		background.setHasListener(true);
		background.revalidate();

		icon = parent.createChild(-1, WidgetType.GRAPHIC);
		icon.setOriginalWidth(BUTTON_SIZE - 6);
		icon.setOriginalHeight(BUTTON_SIZE - 6);
		icon.setOriginalX(BUTTON_X + 3);
		icon.setOriginalY(BUTTON_Y + 3);
		icon.setItemId(ItemID.SLAYER_HELM);
		icon.setItemQuantity(1);
		icon.setItemQuantityMode(ItemQuantityMode.NEVER);
		icon.revalidate();
		syncButton();
	}

	private void syncButton()
	{
		if (background == null)
		{
			return;
		}
		background.setSpriteId(isActive()
			? SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
			: SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
		background.revalidate();
	}

	private void removeButton()
	{
		if (background != null)
		{
			background.setHidden(true);
			background = null;
		}
		if (icon != null)
		{
			icon.setHidden(true);
			icon = null;
		}
	}
}

