package com.slayerprep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

/** Wiki footnotes: set notes are all-or-nothing, item-linked notes depend on the chosen weapon. */
public class GearNotesTest
{
	private GearData.GearTask tormented;
	private GearAdvisor advisor;

	@Before
	public void setUp() throws Exception
	{
		try (Reader gear = new InputStreamReader(GearNotesTest.class.getResourceAsStream("test-gear.json"), StandardCharsets.UTF_8))
		{
			GearData data = GearData.parse(new Gson(), gear);
			tormented = data.optionsFor("Greater demons").get(0).getTask();
		}
		advisor = new GearAdvisor(Collections.emptyMap());
	}

	private Map<String, SlotChoice> ranged(String... bankItems)
	{
		Map<String, Integer> bank = new HashMap<>();
		for (String item : bankItems)
		{
			bank.put(item, 1);
		}
		return advisor.advise(tormented, ItemSnapshot.empty().withBank(bank)).get("Ranged");
	}

	@Test
	public void partialVoidIsNeverMixedWithOtherArmour()
	{
		Map<String, SlotChoice> set = ranged("Slayer helmet (i)", "Elite void top", "Elite void robe",
			"Black d'hide body", "Black d'hide chaps", "Toxic blowpipe");
		assertEquals("Slayer helmet (i)", set.get("head").getItemName());
		assertEquals("Black d'hide body", set.get("body").getItemName());
		assertEquals("Black d'hide chaps", set.get("legs").getItemName());
	}

	@Test
	public void fullVoidIsChosenAsAWholeSet()
	{
		Map<String, SlotChoice> set = ranged("Slayer helmet (i)", "Void ranger helm", "Elite void top", "Elite void robe",
			"Void knight gloves", "Toxic blowpipe");
		assertEquals("Void ranger helm", set.get("head").getItemName());
		assertEquals("Elite void top", set.get("body").getItemName());
		assertEquals("Elite void robe", set.get("legs").getItemName());
		assertEquals("Void knight gloves", set.get("hands").getItemName());
		assertEquals("With full Elite Void.", set.get("body").getNote());
	}

	@Test
	public void bowOfFaerdhinenNeedsFullCrystal()
	{
		Map<String, SlotChoice> without = ranged("Slayer helmet (i)", "Bow of Faerdhinen", "Rune crossbow");
		assertEquals("Rune crossbow", without.get("weapon").getItemName());

		Map<String, SlotChoice> with = ranged("Slayer helmet (i)", "Bow of Faerdhinen", "Rune crossbow",
			"Crystal helm", "Crystal body", "Crystal legs");
		assertEquals("Bow of Faerdhinen", with.get("weapon").getItemName());
		assertEquals("Crystal helm", with.get("head").getItemName());
	}

	@Test
	public void crossbowOnlyItemsNeedACrossbow()
	{
		assertNull(ranged("Twisted bow", "Twisted buckler").get("shield").getItemName());
		assertEquals("Twisted buckler", ranged("Rune crossbow", "Twisted buckler").get("shield").getItemName());
	}

	@Test
	public void ammoFollowsTheChosenWeapon()
	{
		Map<String, SlotChoice> set = ranged("Toxic blowpipe", "Dragon arrow", "Rada's blessing 4");
		assertEquals("Rada's blessing 4", set.get("ammo").getItemName());
		assertEquals("Only if using a bow of Faerdhinen or toxic blowpipe.", set.get("ammo").getNote());
		assertEquals("Dragon arrow", ranged("Twisted bow", "Dragon arrow", "Rada's blessing 4").get("ammo").getItemName());
	}

	@Test
	public void upgradeHintSkipsIneligibleEntries()
	{
		// nothing owned for the weapon: the hint is the top entry, and the blowpipe (rank 2) is not the hint
		assertEquals("Twisted bow", ranged("Slayer helmet (i)").get("weapon").getNextUpgrade());
		// a bow user should not be told to upgrade to a crossbow-only shield
		assertNull(ranged("Twisted bow").get("shield").getNextUpgrade());
	}
}

package com.slayerprep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Before;
import org.junit.Test;

public class GearOptionsTest
{
	private GearData gearData;

	@Before
	public void setUp() throws Exception
	{
		try (Reader gear = new InputStreamReader(GearOptionsTest.class.getResourceAsStream("test-gear.json"), StandardCharsets.UTF_8))
		{
			gearData = GearData.parse(new Gson(), gear);
		}
	}

	private static List<String> labels(List<GearOption> options)
	{
		return options.stream().map(GearOption::getLabel).collect(Collectors.toList());
	}

	@Test
	public void taskWithOwnTableComesFirstThenGeneric()
	{
		List<GearOption> options = gearData.optionsFor("Gargoyles");
		assertEquals(List.of("Gargoyles", "Generic slayer gear"), labels(options));
		assertEquals(GearOption.Kind.TASK, options.get(0).getKind());
		assertEquals(GearOption.Kind.GENERIC, options.get(1).getKind());
	}

	@Test
	public void taskWithoutOwnTableOffersVariantsThenGeneric()
	{
		List<GearOption> options = gearData.optionsFor("Greater demons");
		assertEquals(List.of("Tormented demon", "Generic slayer gear"), labels(options));
		assertEquals(GearOption.Kind.VARIANT, options.get(0).getKind());
		assertTrue(options.get(0).getTask().getStyles().containsKey("Melee"));
	}

	@Test
	public void unknownTaskOnlyGetsGeneric()
	{
		assertEquals(List.of("Generic slayer gear"), labels(gearData.optionsFor("Cows")));
	}

	@Test
	public void itemIdsAreLookedUpByNormalisedName()
	{
		assertEquals(Integer.valueOf(4151), gearData.itemId("abyssal WHIP").orElse(null));
		assertEquals(Integer.valueOf(11865), gearData.itemId("Slayer helmet (i)").orElse(null));
		assertTrue(gearData.itemId("Fire cape").isEmpty());
	}

	@Test
	public void taskWithoutOwnTableIsNotATaskOption()
	{
		assertTrue(gearData.forTask("Greater demons").isEmpty());
	}
}

package com.slayerprep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ItemMatcherTest
{
	@Test
	public void normalizeStripsDoseWithoutSpace()
	{
		assertEquals("amulet of glory", ItemMatcher.normalize("Amulet of glory(4)"));
	}

	@Test
	public void normalizeStripsChargeStates()
	{
		assertEquals("serpentine helm", ItemMatcher.normalize("Serpentine helm (uncharged)"));
		assertEquals("toxic blowpipe", ItemMatcher.normalize("Toxic blowpipe (empty)"));
		assertEquals("trident of the seas", ItemMatcher.normalize("Trident of the seas (full)"));
		assertEquals("dragon dagger", ItemMatcher.normalize("Dragon dagger(p++)"));
		assertEquals("grimy ranarr weed", ItemMatcher.normalize("Grimy ranarr weed (unf)"));
		assertEquals("antidote++", ItemMatcher.normalize("Antidote++(4)"));
	}

	@Test
	public void normalizeKeepsVariantSuffixes()
	{
		assertEquals("slayer helmet (i)", ItemMatcher.normalize("Slayer helmet (i)"));
		assertEquals("masori body (f)", ItemMatcher.normalize("Masori body (f)"));
		assertEquals("slayer's staff (e)", ItemMatcher.normalize("Slayer's staff (e)"));
		assertEquals("rune platebody (g)", ItemMatcher.normalize("Rune platebody (g)"));
		assertEquals("ranging cape (t)", ItemMatcher.normalize("Ranging cape(t)"));
		assertEquals("dragon platebody (or)", ItemMatcher.normalize("Dragon platebody (or)"));
	}

	@Test
	public void exactMatchIsCaseInsensitiveAndWhole()
	{
		ItemMatcher m = ItemMatcher.exact("Nose peg");
		assertTrue(m.matches("nose PEG"));
		assertFalse(m.matches("Nose pegs"));
	}

	@Test
	public void prefixMatchesTrailingText()
	{
		assertTrue(ItemMatcher.prefix("Fungicide spray").matches("Fungicide spray 10"));
		assertTrue(ItemMatcher.prefix("Antifire potion").matches("Antifire potion(3)"));
		assertTrue(ItemMatcher.prefix("Bullseye lantern").matches("Bullseye lantern (lit)"));
		assertFalse(ItemMatcher.prefix("Fungicide spray").matches("Fungicide"));
	}

	@Test
	public void slayerHelmetMatchesEveryVariant()
	{
		ItemMatcher m = ItemMatcher.slayerHelmet();
		assertTrue(m.matches("Slayer helmet"));
		assertTrue(m.matches("Slayer helmet (i)"));
		assertTrue(m.matches("Black slayer helmet (i)"));
		assertTrue(m.matches("Twisted slayer helmet"));
		assertFalse(m.matches("Helm of neitiznot"));
	}

	@Test
	public void gearItemMatchesDegradedAndNumberedVariants()
	{
		assertTrue(ItemMatcher.item("Ahrim's robetop").matches("Ahrim's robetop 100"));
		assertTrue(ItemMatcher.item("Ardougne cloak").matches("Ardougne cloak 4"));
		assertTrue(ItemMatcher.item("Dragon dagger").matches("Dragon dagger(p++)"));
		assertTrue(ItemMatcher.item("Helm of Neitiznot").matches("Helm of neitiznot"));
		assertFalse(ItemMatcher.item("Rune platebody").matches("Rune platebody (g)"));
		assertFalse(ItemMatcher.item("Fire cape").matches("Infernal cape"));
	}

	@Test
	public void gearSlayerHelmetEntriesAcceptRecolours()
	{
		assertTrue(ItemMatcher.item("Slayer helmet (i)").matches("Black slayer helmet (i)"));
		assertFalse(ItemMatcher.item("Slayer helmet (i)").matches("Slayer helmet"));
		assertTrue(ItemMatcher.item("Slayer helmet").matches("Twisted slayer helmet"));
	}
}

package com.slayerprep;

import static org.junit.Assert.assertEquals;
import java.util.Collections;
import java.util.Map;
import org.junit.Test;

public class ItemSnapshotTest
{
	private static final ItemMatcher NOSE_PEG = ItemMatcher.exact("Nose peg");

	@Test
	public void inventoryItemIsCarried()
	{
		ItemSnapshot s = ItemSnapshot.empty().withInventory(Map.of("Nose peg", 1));
		assertEquals(Ownership.CARRIED, s.find(NOSE_PEG));
	}

	@Test
	public void wornItemIsCarried()
	{
		ItemSnapshot s = ItemSnapshot.empty().withWorn(Map.of("Nose peg", 1));
		assertEquals(Ownership.CARRIED, s.find(NOSE_PEG));
	}

	@Test
	public void bankItemIsInBank()
	{
		ItemSnapshot s = ItemSnapshot.empty().withBank(Map.of("Nose peg", 3));
		assertEquals(Ownership.IN_BANK, s.find(NOSE_PEG));
	}

	@Test
	public void carriedBeatsBank()
	{
		ItemSnapshot s = ItemSnapshot.empty().withBank(Map.of("Nose peg", 3)).withInventory(Map.of("Nose peg", 1));
		assertEquals(Ownership.CARRIED, s.find(NOSE_PEG));
	}

	@Test
	public void groupStorageItemIsInGroupBank()
	{
		ItemSnapshot s = ItemSnapshot.empty().withGroupBank(Map.of("Nose peg", 1));
		assertEquals(Ownership.IN_GROUP_BANK, s.find(NOSE_PEG));
		assertEquals(Ownership.IN_BANK, s.withBank(Map.of("Nose peg", 1)).find(NOSE_PEG));
	}

	@Test
	public void absentItemIsMissing()
	{
		assertEquals(Ownership.MISSING, ItemSnapshot.empty().find(NOSE_PEG));
	}

	@Test
	public void findReturnsMatchingItemName()
	{
		ItemSnapshot s = ItemSnapshot.empty().withBank(Map.of("Black slayer helmet (i)", 1));
		assertEquals("Black slayer helmet (i)", s.findName(ItemMatcher.slayerHelmet()).orElse(null));
		assertEquals(Collections.emptyMap(), s.getInventory());
	}
}

package com.slayerprep;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PrepResultTest
{
	private static final SlayerTask TASK = new SlayerTask("Gargoyles", 100, null);
	private static final Requirement HAMMER = Requirement.required(ItemMatcher.exact("Rock hammer"));

	private static PrepResult result(List<RequirementStatus> requirements, Map<String, Map<String, SlotChoice>> gear, String style)
	{
		return new PrepResult(TASK, requirements, gear, Collections.emptyList(), null, null, Collections.emptyList(),
			Collections.emptyMap(), style, true);
	}

	private static SlotChoice choice(String item, Ownership ownership)
	{
		return new SlotChoice(item, item, ownership, null, null);
	}

	@Test
	public void readyWhenRequiredItemsAndSelectedStyleGearAreCarried()
	{
		PrepResult r = result(
			List.of(new RequirementStatus(HAMMER, Ownership.CARRIED, "Rock hammer")),
			Map.of("Melee", Map.of("weapon", choice("Abyssal whip", Ownership.CARRIED), "ring", new SlotChoice(null, null, Ownership.MISSING, "Ultor ring", null))),
			"Melee");
		assertTrue(r.isReady());
	}

	@Test
	public void notReadyWhileARequiredItemIsInTheBank()
	{
		PrepResult r = result(
			List.of(new RequirementStatus(HAMMER, Ownership.IN_BANK, "Rock hammer")),
			Map.of("Melee", Map.of("weapon", choice("Abyssal whip", Ownership.CARRIED))),
			"Melee");
		assertFalse(r.isReady());
	}

	@Test
	public void notReadyWhileSelectedStyleGearIsInTheBank()
	{
		PrepResult r = result(
			List.of(new RequirementStatus(HAMMER, Ownership.CARRIED, "Rock hammer")),
			Map.of("Melee", Map.of("weapon", choice("Abyssal whip", Ownership.IN_BANK)),
				"Ranged", Map.of("weapon", choice("Toxic blowpipe", Ownership.CARRIED))),
			"Melee");
		assertFalse(r.isReady());
		assertTrue(result(List.of(), r.getGear(), "Ranged").isReady());
	}

	@Test
	public void recommendedItemsDoNotBlockReadiness()
	{
		Requirement optional = Requirement.recommended(ItemMatcher.exact("Antifire potion"));
		PrepResult r = result(List.of(new RequirementStatus(optional, Ownership.MISSING, null)), Collections.emptyMap(), null);
		assertTrue(r.isReady());
	}

	@Test
	public void gearStillInBankIsCounted()
	{
		PrepResult r = result(List.of(),
			Map.of("Melee", Map.of("weapon", choice("Abyssal whip", Ownership.IN_BANK), "head", choice("Slayer helmet (i)", Ownership.IN_BANK),
				"cape", choice("Fire cape", Ownership.CARRIED))),
			"Melee");
		assertTrue(r.gearInBank().containsAll(List.of("Abyssal whip", "Slayer helmet (i)")));
		assertFalse(r.gearInBank().contains("Fire cape"));
	}
}

